75	+// primaryRepoPlacement picks the entry's PROCESSING-PRIMARY placement — the
76	+// cell that does the repo's heavy lifting (trails, runners, checkpoint
77	+// ingest), which is where searchable content originates. Selection order:
78	+//
79	+//  1. the placement named by core's explicit `primaries.processing` ULID;
80	+//  2. fallback for rows predating that field: the placement whose ID equals
81	+//     the entry's own ID, else the first (the BFF's canonicalPlacement
82	+//     convention, which processing-primary formalizes).
83	+//
84	+// Selection must never key on the Mirror flag: real /repos rows mark every
85	+// placement Mirror:true, primary included. (The other primary, data_primary,
86	+// is the git-data writer — GitHub itself for github mirrors — so it can never
87	+// route a search.)
88	+//
89	+// ok is false when the chosen placement is not routable: it carries no ID, or
90	+// it is not ready (a ready mirror is no substitute — it may predate the
91	+// clone). Status is required over the wire, so the empty-status arm is
92	+// defensive; any unrecognized future status is treated as not ready, which
93	+// skips the repo WITH a report rather than searching an unknown state.
94	+func primaryRepoPlacement(r coreapi.RepoIndexEntry) (coreapi.RepoPlacement, bool) {
95	+	p := r.Placements[0]
96	+	pick := func(id string) bool {
97	+		if id == "" {
98	+			return false
99	+		}
100	+		for _, c := range r.Placements {
101	+			if c.ID == id {
102	+				p = c
103	+				return true
104	+			}
105	+		}
106	+		return false
107	+	}
108	+	picked := false
109	+	if primaries, ok := r.Primaries.Get(); ok {
110	+		picked = pick(strings.TrimSpace(primaries.Processing))
111	+	}
112	+	if !picked {
113	+		pick(r.ID)
114	+	}
115	+	if strings.TrimSpace(p.ID) == "" {
116	+		return coreapi.RepoPlacement{}, false
117	+	}
118	+	if p.Status != "" && p.Status != coreapi.RepoPlacementStatusReady {
119	+		return coreapi.RepoPlacement{}, false
120	+	}
121	+	return p, true
122	 }
